D.agy=new A.hQ("Unpaid guests","When a guest leaves and the guesthouse portal shows money still owed, the guest is told at once to pay within 30 days. NamStay reminds them on day 7, 20 and 28 (you can also call, WhatsApp or SMS them here). After 30 days they go on the unpaid list: every guesthouse is warned when that phone number books. When the guesthouse records the payment, the guest comes off the list automatically.",null)
D.agA=new A.hQ("NamStay bank account",'The account where owners pay NamStay. Only the super admin and admins with the "NamStay bank details" right can change it. Every admin is told of a change, and owners see it only after 24 hours. If a change looks wrong, any admin can revoke it in those 24 hours.',null)
D.agM=new A.hQ("Commission guesthouses","Guesthouses that pay NamStay a commission for each booking made in the app, instead of a monthly fee. They are never blocked automatically: only by hand in NamStay Billing when an invoice is not paid. Each guesthouse can have its own rate; if not, the general rate is used.",null)
D.agN=new A.hQ("Bypass check","A walk-in is flagged when its phone number belongs to a NamStay guest who, in the 30 days before, looked at that guesthouse, chatted with it, or made an app booking that was not paid. It may be a guest who came through NamStay but was recorded as a walk-in. Check it (call the owner or the guest), then you can add the commission. The owner is told and can answer in the help desk.",null)
